import{_ as e,o as d,c as o,ag as r}from"./chunks/framework.DNmTgtHf.js";const p=JSON.parse('{"title":"Part 27 — Debugging & Production Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/parts/Part_27_Debugging.md","filePath":"todo/study_plan/parts/Part_27_Debugging.md"}'),a={name:"todo/study_plan/parts/Part_27_Debugging.md"};function i(s,t,n,l,c,h){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="part-27-—-debugging-production-troubleshooting" tabindex="-1">Part 27 — Debugging &amp; Production Troubleshooting <a class="header-anchor" href="#part-27-—-debugging-production-troubleshooting" aria-label="Permalink to &quot;Part 27 — Debugging &amp; Production Troubleshooting&quot;">​</a></h1><blockquote><p><strong>Sprint allocation:</strong> Light touch — fold into spare slots. <strong>Budget: ~1-2 hrs (overflow slot).</strong></p></blockquote><h2 id="_27-debugging-production-troubleshooting-—-topic-inventory" tabindex="-1">27 Debugging &amp; Production Troubleshooting — topic inventory <a class="header-anchor" href="#_27-debugging-production-troubleshooting-—-topic-inventory" aria-label="Permalink to &quot;27 Debugging &amp; Production Troubleshooting — topic inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Topic</th><th>Tags</th><th>Tier</th><th>Time</th><th>Done</th><th>Partial</th><th>Grilling</th><th>Visit Again</th><th>Notes</th><th>Resources</th></tr></thead><tbody><tr><td>1</td><td>Thread dumps — jstack, <code>kill -3</code>, capture under load</td><td>🔴 💼</td><td>MP</td><td>2 hrs 20 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: <code>jstack &lt;pid&gt;</code> on a running Spring Boot app, identify RUNNABLE / WAITING / BLOCKED states (20 min)</td></tr><tr><td>2</td><td>Reading thread dumps — find BLOCKED, identify lock contention, deadlocks</td><td>🔴 💼</td><td>D</td><td>3 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>3</td><td>Heap dumps — jmap, <code>-XX:+HeapDumpOnOutOfMemoryError</code></td><td>🔴 💼</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>4</td><td>Heap analysis — Eclipse MAT (dominator tree, retained heap, leak suspects)</td><td>🔴 💼</td><td>D</td><td>3 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: open a sample heap dump (or generate via <code>jmap -dump</code>) in Eclipse MAT, navigate to Leak Suspects report (30 min)</td></tr><tr><td>5</td><td><code>curl -v</code>, <code>openssl s_client</code> (TLS handshake inspection)</td><td>🔴 💼</td><td>MP</td><td>1 hr 30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>(Cross-ref Part 11 + 16)</td></tr><tr><td>6</td><td>tcpdump basics, Wireshark for deep dives</td><td>🔴 💼</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>7</td><td>Slow query logs — MySQL slow_log, Postgres pg_stat_statements</td><td>🔴 💼</td><td>MP</td><td>1 hr 45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: enable <code>log_min_duration_statement = 1000</code> in Postgres, capture a slow query, read the log line (15 min)</td></tr><tr><td>8</td><td>EXPLAIN ANALYZE deeply (cost vs actual rows, where plans go wrong)</td><td>🔴 💼</td><td>D</td><td>2.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>(Cross-ref Part 6)</td></tr><tr><td>9</td><td>Distributed tracing for narrowing failure to a service</td><td>🔴 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>(Cross-ref Part 21)</td></tr><tr><td>10</td><td>Correlation IDs end-to-end</td><td>🔴 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>(Cross-ref Part 21)</td></tr><tr><td>11</td><td>5 whys, fishbone (Ishikawa) analysis</td><td>🔴 💼</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>12</td><td>Reproducing in staging / lower envs</td><td>🔴 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>13</td><td>GC log analysis — gceasy.io, GCViewer</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>14</td><td>Async-profiler — CPU, allocation, lock profiling</td><td>🟠 💼</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>(Cross-ref Part 8)</td></tr><tr><td>15</td><td>JFR — continuous low-overhead profiling in prod</td><td>🟠 💼</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>16</td><td>jstat, jcmd, jinfo, jps — command-line forensics</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>17</td><td>mitmproxy / Charles for HTTP intercept</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>18</td><td>dig, nslookup — DNS forensics</td><td>🟠 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>19</td><td><code>ss</code> / <code>netstat</code> — open connections, TIME_WAIT, port exhaustion</td><td>🟠 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>20</td><td>Lock waits, deadlock graph</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>21</td><td>Replication lag investigation</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>22</td><td>Auto-vacuum / bloat (Postgres)</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>23</td><td>Bisecting bad commits (<code>git bisect</code>)</td><td>🟠 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>24</td><td>Postmortem writing — blameless, action items with owners</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>25</td><td>Incident commander vs comms role separation</td><td>🟠 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>26</td><td>Knowing when to escalate vs continue investigating</td><td>🟠 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>27</td><td>eBPF tooling (bcc-tools, bpftrace) — for the curious</td><td>🟡</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr></tbody></table><h2 id="time-summary" tabindex="-1">Time summary <a class="header-anchor" href="#time-summary" aria-label="Permalink to &quot;Time summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Hours (zero baseline)</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>🔴 MUST only (Sprint priority — 3-month plan)</td><td>~23.58 hrs</td><td>~2.15 wk</td><td></td></tr><tr><td>🔴 + 🟠 HIGH (must + high — senior coverage)</td><td>~43.58 hrs</td><td>~3.95 wk</td><td></td></tr><tr><td>Full Part (all items including 🟡)</td><td>~45.08 hrs</td><td>~4.1 wk</td><td></td></tr></tbody></table><h2 id="frequently-asked" tabindex="-1">Frequently asked <a class="header-anchor" href="#frequently-asked" aria-label="Permalink to &quot;Frequently asked&quot;">​</a></h2><ol><li><strong>Q:</strong> Walk me through diagnosing a Java service that&#39;s &quot;hung&quot; in production. <ul><li><strong>Why asked:</strong> Daily senior triage skill. (1) <code>kill -3 &lt;pid&gt;</code> or <code>jstack &lt;pid&gt;</code> for thread dump. (2) Look for BLOCKED threads — what are they waiting on? (3) Look for cycles in lock contention. (4) Check thread pool exhaustion (all worker threads waiting on something). (5) Cross-check with <code>top</code> (CPU pinned vs idle), GC logs (full GC pause?), DB connection pool. (6) Get a heap dump if memory looks suspicious.</li></ul></li><li><strong>Q:</strong> Read this Postgres EXPLAIN. Estimated rows 100, actual rows 100,000. What&#39;s wrong? <ul><li><strong>Why asked:</strong> Diagnostic depth. Stale planner statistics. Fix: <code>ANALYZE &lt;table&gt;</code> to update. Cause: heavy write traffic since last autovacuum run, or skewed data distribution. May need <code>default_statistics_target</code> increase for that column.</li></ul></li><li><strong>Q:</strong> How do you narrow down a failure across 5 microservices? <ul><li><strong>Why asked:</strong> Distributed-systems debugging. (1) Use correlation ID from the failed request to trace through Datadog / OpenTelemetry. (2) Identify which span errored or had high latency. (3) Drill into that service&#39;s logs filtered by same correlationId. (4) Cross-check with that service&#39;s metrics during the same window. (5) Reproduce in staging if possible.</li></ul></li><li><strong>Q:</strong> Your service shows OOM in production every 2 weeks. How do you find the leak? <ul><li><strong>Why asked:</strong> Memory-leak diagnosis. (1) Enable <code>-XX:+HeapDumpOnOutOfMemoryError -XX:HeapDumpPath=/tmp/heap.hprof</code>. (2) When OOM hits, copy the dump. (3) Open in Eclipse MAT. (4) Run &quot;Leak Suspects&quot; report — usually points at the culprit. (5) Drill via Dominator Tree to find what&#39;s retaining the suspect. Common: <code>ThreadLocal</code> not cleared, static <code>List</code> growing unbounded, cache without size limit.</li></ul></li><li><strong>Q:</strong> A spike of 5xx errors started 10 min ago. Walk me through your first 5 minutes. <ul><li><strong>Why asked:</strong> Incident response. (0) Acknowledge in incident channel. (1) Check obvious: recent deploys, recent config changes, recent infrastructure events (AWS console). (2) Check distributed tracing for which service is erroring. (3) Check that service&#39;s logs + metrics. (4) If unclear, get incident commander + comms separation in place. (5) Within 5 min, you should have a hypothesis or &quot;need more time&quot; decision.</li></ul></li><li><strong>Q:</strong> Your TCP connection pool to a downstream is full. How do you confirm + fix? <ul><li><strong>Why asked:</strong> Operational depth. Confirm: <code>ss -tn state established &#39;( sport = :{port} )&#39;</code> to count connections. Check HikariCP active vs idle metrics. Logs may show &quot;connection acquisition timeout.&quot; Fix: depends on root cause. (1) Downstream slowed (mitigate: timeout + circuit breaker). (2) Connection leak (find unclosed Statement / Result). (3) Pool too small (increase based on Little&#39;s Law).</li></ul></li><li><strong>Q:</strong> Postgres shows replication lag &gt; 30 seconds. What&#39;s likely happening? <ul><li><strong>Why asked:</strong> Replication operational issue. Causes: (1) Heavy write traffic on primary &gt; replica can apply. (2) Long-running query on replica blocking WAL replay. (3) Network bandwidth between primary + replica. (4) Replica I/O saturation. Check <code>pg_stat_replication</code> on primary + <code>pg_stat_wal_receiver</code> on replica. Decision: route reads back to primary temporarily; investigate root cause.</li></ul></li></ol><h2 id="trick-questions-gotchas" tabindex="-1">Trick questions / gotchas <a class="header-anchor" href="#trick-questions-gotchas" aria-label="Permalink to &quot;Trick questions / gotchas&quot;">​</a></h2><ol><li><strong>Q:</strong> Your thread dump shows 200 threads all WAITING on the same object. The lock holder is not in the dump. Why? <ul><li><strong>Gotcha:</strong> Lock holder may be in a non-Java thread (native code, GC thread), or the dump was captured between the lock-release and another thread acquiring. Take 3-5 dumps 10 seconds apart — pattern over time reveals the actual contention.</li></ul></li><li><strong>Q:</strong> You ran <code>jmap -dump</code> on a production process. The process became unresponsive for 30 seconds. Why? <ul><li><strong>Gotcha:</strong> <code>jmap -dump:live</code> triggers a full GC + suspends the JVM for the dump duration. For 8GB heap, can be tens of seconds. In production: use <code>jcmd &lt;pid&gt; GC.heap_dump &lt;file&gt;</code> (newer API, less impactful) or pre-configure <code>-XX:+HeapDumpOnOutOfMemoryError</code> so dump only happens on OOM (when the process is dying anyway).</li></ul></li><li><strong>Q:</strong> A spike in latency. CPU is at 5%. RAM has lots of free. DB has no slow queries. Where&#39;s the latency? <ul><li><strong>Gotcha:</strong> Likely network (DNS resolution slow), downstream service (external API), thread pool exhaustion (all worker threads waiting), or GC pause (paused JVM doesn&#39;t show high CPU during pause). Look at trace spans, not raw resource metrics.</li></ul></li><li><strong>Q:</strong> Your service was sluggish. You restarted it. Performance returned. Did you fix the bug? <ul><li><strong>Gotcha:</strong> No — you cleared symptom, not root cause. Get a thread dump + heap dump BEFORE restarting (or even after — the restart loses evidence). &quot;Reboot and shrug&quot; is the SDE2 reflex; &quot;capture then restart&quot; is the senior move.</li></ul></li></ol><h2 id="mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" tabindex="-1">Mastery candidates (top 3–5 from this Part — suggestions, not commitments) <a class="header-anchor" href="#mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" aria-label="Permalink to &quot;Mastery candidates (top 3–5 from this Part — suggestions, not commitments)&quot;">​</a></h2><ul><li><strong>Thread dump analysis fluency</strong> (~3.5 hrs combined rows 1+2) — most senior daily skill. Practice with several real dumps. Understand BLOCKED, WAITING, deadlock detection output, lock chain reconstruction.</li><li><strong>Heap dump leak hunting</strong> (~3.5 hrs combined rows 3+4) — most production-critical OOM skill. Eclipse MAT navigation: Dominator Tree, retained heap, leak suspects, OQL queries.</li><li><strong>Postmortem writing</strong> (~2 hrs row 24) — STAR-style postmortem with blameless tone, action items + owners. Becomes promotion material when done well.</li><li><strong>Incident response playbook for KYC verification failures</strong> (~2.5 hrs combined) — runbook entries for top 5 likely failure modes. Test in a game day.</li></ul><h2 id="hands-on-exercises-practice-advanced" tabindex="-1">Hands-on exercises (Practice + Advanced) <a class="header-anchor" href="#hands-on-exercises-practice-advanced" aria-label="Permalink to &quot;Hands-on exercises (Practice + Advanced)&quot;">​</a></h2><p>Warm-up debugging exercises are listed inline in the topic-table Resources column (counted in main Time summary). Longer exercises below are tracked separately.</p><h3 id="practice-—-mid-level-30-60-min-each" tabindex="-1">Practice — mid-level (~30-60 min each) <a class="header-anchor" href="#practice-—-mid-level-30-60-min-each" aria-label="Permalink to &quot;Practice — mid-level (~30-60 min each)&quot;">​</a></h3><ol><li><strong>Thread dump analysis on a deadlocked process</strong> (~60 min) — write a small Java app that deadlocks two threads on two locks acquired in opposite order. Run, capture <code>jstack</code>, find &quot;deadlock detected&quot; report. Reconstruct the cycle. Fix via consistent lock ordering.</li><li><strong>Heap dump → leak hunt in Eclipse MAT</strong> (~60 min) — write a small app that leaks (e.g., static List&lt;byte[]&gt; appending indefinitely). Generate heap dump. Open in MAT. Find leak suspect via Dominator Tree.</li><li><strong>Slow query log + EXPLAIN ANALYZE fix</strong> (~45 min) — Postgres with <code>log_min_duration_statement = 100</code>. Run a query that does a sequential scan on 1M rows. Capture log. Add index. Verify EXPLAIN shows index scan. Confirm log no longer shows the slow query.</li></ol><h3 id="advanced-—-senior-grade-depth-60-min-each" tabindex="-1">Advanced — senior-grade depth (~60+ min each) <a class="header-anchor" href="#advanced-—-senior-grade-depth-60-min-each" aria-label="Permalink to &quot;Advanced — senior-grade depth (~60+ min each)&quot;">​</a></h3><ol start="4"><li><strong>Production-style debugging exercise</strong> (~90 min) — set up a Spring Boot app with deliberate bugs (a memory leak + a thread deadlock + a slow query). Use the full toolbox: jstack, jmap, EXPLAIN, distributed tracing. Document each diagnosis step. Practice the workflow.</li><li><strong>Blameless postmortem template + walkthrough</strong> (~75 min) — write a postmortem template (Summary, Timeline, Root cause, Detection, Mitigation, Action items + owners). Apply to a real (or simulated) incident. Get peer review on the tone and rigor.</li></ol><h3 id="hands-on-time-summary-practice-advanced-only" tabindex="-1">Hands-on time summary (Practice + Advanced only) <a class="header-anchor" href="#hands-on-time-summary-practice-advanced-only" aria-label="Permalink to &quot;Hands-on time summary (Practice + Advanced only)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tier</th><th>Total time</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>Practice (mid-level)</td><td>~2.75 hrs</td><td>~0.25 wk</td><td></td></tr><tr><td>Advanced (senior-grade)</td><td>~2.75 hrs</td><td>~0.25 wk</td><td></td></tr><tr><td><strong>Combined hands-on (Practice + Advanced)</strong></td><td><strong>~5.5 hrs</strong></td><td><strong>~0.5 wk</strong></td><td></td></tr></tbody></table><blockquote><p>Warm-up exercises (counted in main Time summary above) total ~65 min for Part 27 across 3 in-table warm-ups.</p></blockquote><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. Thread dump diagnostic — first sweep?</strong> A. Count threads by state (RUNNABLE, WAITING, BLOCKED). Many BLOCKED on same monitor → lock contention. &quot;Deadlock detected&quot; line → JVM found a cycle. All worker threads WAITING on the same downstream → pool exhaustion or downstream slow.</p><p><strong>Q. Heap dump leak hunt — first tool?</strong> A. Eclipse MAT &quot;Leak Suspects&quot; report. Usually points directly at the leak. Drill via Dominator Tree to find what&#39;s retaining the suspect (often a static field or ThreadLocal).</p><p><strong>Q. EXPLAIN — what does estimated vs actual row mismatch mean?</strong> A. Planner statistics are stale or skewed. Run <code>ANALYZE</code> to update. If persistent, may need <code>default_statistics_target</code> increase or query rewrite.</p><p><strong>Q. Incident — first 60 seconds?</strong> A. (1) Acknowledge in channel. (2) Check recent deploys + config changes + infra events. (3) Form initial hypothesis or admit &quot;investigating.&quot; Don&#39;t restart anything before capturing evidence.</p><p><strong>Q. Reboot vs root cause — senior reflex?</strong> A. Capture evidence (thread dump, heap dump) BEFORE restarting. Restart clears symptom but loses diagnostic info. Senior move: capture then restart, investigate root cause out-of-band.</p><p><strong>Q. 5 whys + fishbone — when each?</strong> A. 5 whys: linear root-cause drill from symptom backward. Fast, good for clear failures. Fishbone: multi-category cause exploration (people, process, technology, environment). Better for complex / multi-factor failures.</p>',28)])])}const g=e(a,[["render",i]]);export{p as __pageData,g as default};
